const at = (o, p) => p.split('.').reduce((obj, key) => (obj === null || obj === undefined) ? undefined : obj[key], o);
const event = String(at(root, 'event') || '');
if (event !== 'taskCommentPosted') return '';
const comment = at(root, 'history_items.0.comment');
if (comment === undefined || comment === null) return '';
let text;
if (Array.isArray(comment)) {
  text = comment.map((seg) => (seg && typeof seg === 'object' ? (seg.text || '') : String(seg))).join('');
} else if (typeof comment === 'object') {
  text = comment.text || comment.comment_text || '';
} else {
  text = String(comment);
}
return String(text || '').trim();
